import fs from "node:fs";
import path from "node:path";
import { getRoots } from "./paths.js";
import { readRules, renderSkill, SKILLS } from "./skills.js";
import { AGENT_HOSTS, type AgentHost } from "../../schemas/specx-config.js";

const AGENT_LABELS: Record<AgentHost, string> = {
  codex: "Codex",
  claude: "Claude Code",
  cursor: "Cursor",
  copilot: "GitHub Copilot",
};
const SKILL_DIRS: Record<AgentHost, string> = {
  codex: ".agents/skills",
  claude: ".claude/skills",
  cursor: ".cursor/skills",
  copilot: ".github/skills",
};
// Generated by earlier SpecX versions; removed so agents never see conflicting workflows.
const LEGACY_SKILLS = ["discover", "specify", "propose", "approve", "resume", "archive", "build", "critic", "design", "revise", "graph", "sdd", "spec", "specialist", "tasks", "verify"];
const CURSOR_RULE_HEADER = "---\ndescription: SpecX rules\nglobs:\nalwaysApply: true\n---\n\n";

export function parseAgentSelection(value: string): AgentHost[] {
  const selected = value.split(",").map((item) => item.trim().toLowerCase()).filter(Boolean);
  if (selected.length === 0) throw new Error("Select at least one agent integration.");
  const invalid = selected.filter((item) => !AGENT_HOSTS.includes(item as AgentHost));
  if (invalid.length) throw new Error(`Unknown agent(s): ${invalid.join(", ")}. Choose from: ${AGENT_HOSTS.join(", ")}.`);
  return [...new Set(selected as AgentHost[])];
}

export function agentLabel(agent: AgentHost): string {
  return AGENT_LABELS[agent];
}

function writeManagedSection(file: string, marker: string, body: string): void {
  const begin = `<!-- specx:${marker}:begin -->`;
  const end = `<!-- specx:${marker}:end -->`;
  const existing = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : "";
  const section = `${begin}\n${body.trim()}\n${end}`;
  const start = existing.indexOf(begin);
  const finish = start < 0 ? -1 : existing.indexOf(end, start + begin.length);
  const next = start >= 0 && finish >= 0
    ? `${existing.slice(0, start)}${section}${existing.slice(finish + end.length)}`
    : `${existing.trimEnd()}${existing ? "\n\n" : ""}${section}\n`;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, next, "utf8");
}

function removeManagedSection(file: string, marker: string): void {
  if (!fs.existsSync(file)) return;
  const begin = `<!-- specx:${marker}:begin -->`;
  const end = `<!-- specx:${marker}:end -->`;
  const existing = fs.readFileSync(file, "utf8");
  const start = existing.indexOf(begin);
  const finish = start < 0 ? -1 : existing.indexOf(end, start + begin.length);
  if (start < 0 || finish < 0) return;
  const next = `${existing.slice(0, start)}${existing.slice(finish + end.length)}`.trim();
  if (next) fs.writeFileSync(file, `${next}\n`, "utf8");
  else fs.rmSync(file, { force: true });
}

function removeLegacy(root: string): void {
  for (const dir of Object.values(SKILL_DIRS)) {
    for (const skill of LEGACY_SKILLS) fs.rmSync(path.join(root, dir, `specx-${skill}`), { recursive: true, force: true });
  }
  fs.rmSync(path.join(root, ".specx", "commands"), { recursive: true, force: true });
  const claudeCommands = path.join(root, ".claude", "commands", "specx");
  const cursorCommands = path.join(root, ".cursor", "commands");
  for (const skill of [...SKILLS, ...LEGACY_SKILLS]) {
    fs.rmSync(path.join(claudeCommands, `${skill}.md`), { force: true });
    fs.rmSync(path.join(cursorCommands, `specx-${skill}.md`), { force: true });
  }
  if (fs.existsSync(claudeCommands) && fs.readdirSync(claudeCommands).length === 0) fs.rmdirSync(claudeCommands);
  const oldRules = path.join(root, ".specx", "AGENTS.md");
  if (fs.existsSync(oldRules) && fs.readFileSync(oldRules, "utf8").includes("# specX agent rules")) fs.rmSync(oldRules, { force: true });
}

function writeSkills(destination: string): void {
  for (const skill of SKILLS) {
    const name = `specx-${skill}`;
    fs.mkdirSync(path.join(destination, name), { recursive: true });
    fs.writeFileSync(path.join(destination, name, "SKILL.md"), renderSkill(skill, name), "utf8");
  }
}

function removeSkills(destination: string): void {
  for (const skill of SKILLS) fs.rmSync(path.join(destination, `specx-${skill}`), { recursive: true, force: true });
}

/** Writes the rules everywhere an agent looks, plus the three skills for each selected host. */
export function generateAgentIntegrations(projectRoot: string | undefined, selectedHosts: AgentHost[]): string[] {
  const { projectRoot: root, specxDir } = getRoots(projectRoot);
  const selected = new Set(selectedHosts);
  const rules = readRules();
  const written: string[] = [];
  removeLegacy(root);

  for (const host of AGENT_HOSTS) {
    const destination = path.join(root, SKILL_DIRS[host]);
    try {
      if (selected.has(host)) { writeSkills(destination); written.push(destination); }
      else removeSkills(destination);
    } catch (err) {
      if (host !== "codex" || !["EACCES", "EPERM"].includes((err as NodeJS.ErrnoException).code ?? "")) throw err;
      console.warn(`Skipping read-only Codex skills directory: ${destination}`);
    }
  }

  const rulesFile = path.join(specxDir, "RULES.md");
  writeManagedSection(rulesFile, "rules", rules);
  written.push(rulesFile);

  const agentsFile = path.join(root, "AGENTS.md");
  writeManagedSection(agentsFile, "agents", rules);
  written.push(agentsFile);

  const claudeFile = path.join(root, "CLAUDE.md");
  if (selected.has("claude")) { writeManagedSection(claudeFile, "claude", rules); written.push(claudeFile); }
  else removeManagedSection(claudeFile, "claude");

  const copilotFile = path.join(root, ".github", "copilot-instructions.md");
  if (selected.has("copilot")) { writeManagedSection(copilotFile, "copilot", rules); written.push(copilotFile); }
  else removeManagedSection(copilotFile, "copilot");

  const cursorRule = path.join(root, ".cursor", "rules", "specx.mdc");
  if (selected.has("cursor")) {
    fs.mkdirSync(path.dirname(cursorRule), { recursive: true });
    fs.writeFileSync(cursorRule, `${CURSOR_RULE_HEADER}${rules}\n`, "utf8");
    written.push(cursorRule);
  } else if (fs.existsSync(cursorRule) && /^---\ndescription: SpecX/.test(fs.readFileSync(cursorRule, "utf8"))) {
    fs.rmSync(cursorRule, { force: true });
  }
  return written;
}
